CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, username VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'staff'); INSERT INTO users (name, username, password, role) VALUES ('Main Admin', 'admin', '$2y$10$A0XE0jGK8GJzx1uhp47g7.6bYsCT3Be6ZEbIBvaRDAZ4tMZfsrCPW', 'admin'); CREATE TABLE suppliers (id INT AUTO_INCREMENT PRIMARY KEY, supplier_name VARCHAR(120) NOT NULL); INSERT INTO suppliers (supplier_name) VALUES ('Indian grocery'),('Local Indian Grocery'),('Disposal'),('Supermarket'),('Fruit & Veggies'),('Coffee'),('Frozen goods'); CREATE TABLE user_supplier_access (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, supplier_id INT NOT NULL); CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, supplier_id INT NOT NULL, product_name VARCHAR(150) NOT NULL, unit VARCHAR(20) NOT NULL DEFAULT 'kg', soh INT NOT NULL DEFAULT 0, csoh INT NOT NULL DEFAULT 0, op INT NOT NULL DEFAULT 0); INSERT INTO products (supplier_id, product_name, unit, soh, csoh, op) VALUES (1, 'Basmati Rice', 'kg', 20, 50, 30),(1, 'Toor Dal', 'kg', 15, 40, 25),(2, 'Masala Pack', 'box', 25, 25, 0),(3, 'Paper Cups', 'carton', 10, 60, 50),(4, 'Soft Drink', 'box', 72, 100, 28),(5, 'Tomato', 'kg', 11, 35, 24),(6, 'Coffee Beans', 'kg', 8, 30, 22),(7, 'Frozen Fries', 'carton', 16, 45, 29);
